-- 0af047b6 | ما هي قصة نبي الله موسى عليه السلام مع فرعون؟
UPDATE qa_questions SET
  answer = 'أرسل اللهُ موسى عليه السلام إلى فرعونَ لطغيانه ﴿ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ﴾ [طه: ٢٤]، فادّعى فرعونُ الألوهيةَ ﴿فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ﴾ [النازعات: ٢٤] واستكبر هو وجنودُه في الأرض بغير الحقّ [القصص: ٣٩]، وأيّد اللهُ موسى بآياتٍ منها انقلابُ العصا حيّةً تسعى وخروجُ يده بيضاءَ من غير سوءٍ [طه: ١٩-٢٢]. فلمّا أصرّوا فلَق اللهُ البحرَ بضربةِ العصا، فنجّى موسى ومن معه أجمعين ثم أغرقَ الآخرين [الشعراء: ٦٣، ٦٥-٦٦]. ولم ينفعْ فرعونَ إيمانُه حين أدركه الغرق، فقيل له: ﴿ءَآلْـَٰٔنَ وَقَدْ عَصَيْتَ قَبْلُ﴾ [يونس: ٩٠-٩١].',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): طه ١٩-٢٢ و٢٤، والقصص ٣٨-٣٩، والنازعات ٢٤، والشعراء ٦٣ و٦٥-٦٦، ويونس ٩٠-٩١ | الكلمات المفتاحية: قصة موسى وفرعون',
  evidence = 'نصُّ التكليف: ﴿ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ﴾ [طه: ٢٤]. ودعوى فرعونَ الألوهيةَ منصوصةٌ في موضعين: ﴿فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ﴾ [النازعات: ٢٤]، و﴿وَقَالَ فِرْعَوْنُ يَٰٓأَيُّهَا ٱلْمَلَأُ مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِى﴾ [القصص: ٣٨]، واستكبارُه ومَن معه: ﴿وَٱسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ﴾ [القصص: ٣٩]. والآيتانِ اللتان أُيِّد بهما موسى: ﴿قَالَ أَلْقِهَا يَٰمُوسَىٰ﴾ ﴿فَأَلْقَىٰهَا فَإِذَا هِىَ حَيَّةٌۭ تَسْعَىٰ﴾ [طه: ١٩-٢٠]، و﴿وَٱضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ءَايَةً أُخْرَىٰ﴾ [طه: ٢٢]. وفَلْقُ البحر ثم النجاةُ والإغراق: ﴿فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ ۖ فَٱنفَلَقَ﴾ [الشعراء: ٦٣]، ﴿وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ﴾ ﴿ثُمَّ أَغْرَقْنَا ٱلْءَاخَرِينَ﴾ [الشعراء: ٦٥-٦٦]. وقولُ فرعونَ عند الغرق ﴿ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ﴾ رُدَّ عليه في الآية بعدَها: ﴿ءَآلْـَٰٔنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ﴾ [يونس: ٩٠-٩١].',
  verification_status = 'verified'
WHERE id = '0af047b6-d0c1-497e-8a32-4ad2ef29838a'
  AND reference = 'القرآن الكريم | الكلمات المفتاحية: قصة موسى وفرعون'
  AND evidence = 'قصة مفصَّلة مكرَّرة في مواضع متعددة من القرآن الكريم.'
  AND answer = 'أرسل الله موسى لفرعون الذي استكبر وادّعى الألوهية، فأيّده الله بمعجزات كالعصا واليد البيضاء، وحين أصرّ فرعون وقومه على الكفر أغرقهم الله في البحر بعد أن نجّى موسى وقومه.';

-- 060849ce | ما هي أبرز قصص الأنبياء المذكورة في القرآن؟
UPDATE qa_questions SET
  answer = 'من أبرزها: قصّةُ آدمَ وإخراجِه من الجنّة [البقرة: ٣٦]، ونوحٍ وصنعِه الفلكَ بوحي الله [هود: ٣٧]، وإبراهيمَ وإسماعيلَ إذ يرفعان القواعدَ من البيت [البقرة: ١٢٧]، ويوسفَ وإخوتِه إذ ألقَوه في غيابة الجُبّ [يوسف: ١٥]، وموسى وفرعونَ وفَلْقِ البحر [الشعراء: ٦٣]، وعيسى وولادتِه من غير أن يمسَّ أمَّه بشرٌ [مريم: ٢٠-٢١]، ويونسَ إذ التقمه الحوتُ فنادى في الظلمات فاستجاب اللهُ له ونجّاه من الغمّ [الصافات: ١٤٢-١٤٤، والأنبياء: ٨٧-٨٨].',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): البقرة ٣٦ و١٢٧، وهود ٣٧، ويوسف ١٥، والشعراء ٦٣، ومريم ٢٠-٢١، والصافات ١٤٢-١٤٤، والأنبياء ٨٧-٨٨ | الكلمات المفتاحية: قصص الأنبياء',
  evidence = 'لكلِّ قصّةٍ ممّا ذُكر موضعُها: آدمُ وخروجُه من الجنّة ﴿فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ﴾ [البقرة: ٣٦]؛ ونوحٌ وسفينتُه ﴿وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا﴾ [هود: ٣٧]؛ وإبراهيمُ عند البيت — والمنصوصُ **رفعُ القواعد مع إسماعيلَ** لا ابتداءُ البناء وحدَه: ﴿وَإِذْ يَرْفَعُ إِبْرَٰهِۦمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَٰعِيلُ﴾ [البقرة: ١٢٧]؛ ويوسفُ وإخوتُه ﴿فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ﴾ [يوسف: ١٥]؛ وموسى وفرعونُ ﴿فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ ۖ فَٱنفَلَقَ﴾ [الشعراء: ٦٣]؛ وعيسى وولادتُه ﴿قَالَتْ أَنَّىٰ يَكُونُ لِى غُلَٰمٌۭ وَلَمْ يَمْسَسْنِى بَشَرٌۭ وَلَمْ أَكُ بَغِيًّۭا﴾ ﴿قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌۭ﴾ [مريم: ٢٠-٢١]؛ ويونسُ والحوتُ ﴿فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌۭ﴾ ﴿فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ٱلْمُسَبِّحِينَ﴾ ﴿لَلَبِثَ فِى بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ﴾ [الصافات: ١٤٢-١٤٤]، ودعاؤُه ﴿فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ﴾ ﴿فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ﴾ [الأنبياء: ٨٧-٨٨].',
  verification_status = 'verified'
WHERE id = '060849ce-80ac-4fde-93aa-ad8647ad2cc0'
  AND reference = 'القرآن الكريم | الكلمات المفتاحية: قصص الأنبياء'
  AND evidence = 'قصص مذكورة تفصيلاً في مواضع متعددة من القرآن الكريم.'
  AND answer = 'من أبرزها: قصة آدم وخروجه من الجنة، ونوح وسفينته، وإبراهيم وبناء الكعبة، ويوسف وإخوته، وموسى وفرعون، وعيسى وولادته المعجزة، ويونس والحوت — قصص تحمل عبرًا عظيمة تكررت أحداثها بأشكال متنوعة عبر القرآن.';

-- 52f0e8da | ما هي أطول وأقصر سورة في القرآن الكريم؟
UPDATE qa_questions SET
  answer = 'أطولُ سورةٍ بعددِ الآي سورةُ البقرة (٢٨٦ آية). وأمّا الأقصرُ فيُفصَّل: أقلُّ السور عددَ آيٍ ثلاثُ سورٍ مستويةٍ في ثلاثِ آيات، هي العصرُ والكوثرُ والنصر، فلا تنفرد إحداهنّ بذلك؛ والكوثرُ أقصرُهنّ لفظًا وكلماتٍ، فهي أقصرُ سور القرآن بهذا الاعتبار. والعدُّ في هذا كلِّه من مصحف المشروع نفسِه لا من غيره.',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): عدٌّ مباشرٌ من ملفّات السور المئةِ والأربعَ عشرةَ (البقرة ٢٨٦ آية؛ العصر والكوثر والنصر ثلاثُ آياتٍ لكلٍّ) | الكلمات المفتاحية: أطول سورة، أقصر سورة',
  evidence = 'عدٌّ مباشرٌ من ملفّات مصحف المشروع المحلّيّ (`public/data/quran/surah-001.json` … `surah-114.json`، رواية حفص برسم عثماني): أكثرُ السور آيًا سورةُ البقرة (٢٨٦ آية)، وليس بعدها في العدد إلا الشعراءُ (٢٢٧) فالأعرافُ (٢٠٦). وأمّا الأقلُّ آيًا فثلاثُ سورٍ **تستوي** في ثلاثِ آيات: العصر (١٠٣) والكوثر (١٠٨) والنصر (١١٠)؛ فلا تنفرد الكوثرُ بأقلِّ عددِ آيٍ كما كان في ‹أقصر سورة سورة الكوثر (3 آيات)›. وإنّما تنفرد الكوثرُ بأنّها أقصرُهنّ **لفظًا**: أربعَ عشرةَ كلمة، دون العصر (١٨ كلمة) والنصر (٢٤ كلمة).',
  verification_status = 'verified'
WHERE id = '52f0e8da-7281-4ba3-a0cd-8578ca82558f'
  AND reference = 'المصحف الشريف | الكلمات المفتاحية: أطول سورة، أقصر سورة'
  AND evidence = 'حقيقة عددية ثابتة في ترتيب المصحف الشريف.'
  AND answer = 'أطول سورة سورة البقرة (286 آية)، وأقصر سورة سورة الكوثر (3 آيات).';

-- 51fc1bd1 | كم عدد سور القرآن الكريم؟
