-- 53f94ba7 | من هم أصحاب الفروض في الميراث؟
UPDATE qa_questions SET
  answer = 'أصحابُ الفروض هم الوارثون الذين قدَّر اللهُ لهم أنصبةً مسمّاةً في كتابه، لا الأنصبةُ نفسُها. والمنصوصُ عليهم في آيات المواريث: البنتُ والبناتُ، والأبُ، والأمُّ [النساء: ١١]؛ والزوجُ، والزوجاتُ، والأخُ والأختُ من الأمّ [النساء: ١٢]؛ والأختُ فأكثرُ من الأبوين أو من الأب [النساء: ١٧٦]. وتعيينُ الأخوَينِ في الآيتين على هذا الوجه منصوصٌ في المغني (ج٩/ص٦-٧). وأمّا الفروضُ الستّةُ — النصفُ والربعُ والثمنُ والثلثان والثلثُ والسدسُ — فهي أنصبتُهم، لا هم.',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): النساء ١١ و١٢ و١٧٦؛ المغني لابن قدامة: ج٩/ص٦ وج٩/ص٧ (كتاب الفرائض) | الكلمات المفتاحية: أصحاب الفروض، علم المواريث',
  evidence = 'أصحابُ الفروض أشخاصٌ سمّى اللهُ لهم أنصبةً مقدَّرةً، والمنصوصُ عليهم في ثلاث آيات: (١) النساء ١١ وفيها البناتُ والبنتُ والأبوان: ﴿فَإِن كُنَّ نِسَآءًۭ فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ ۖ وَإِن كَانَتْ وَٰحِدَةًۭ فَلَهَا ٱلنِّصْفُ ۚ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌۭ ۚ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدٌۭ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ﴾؛ (٢) والنساء ١٢ وفيها الزوجُ والزوجاتُ ثم أخٌ أو أختٌ: ﴿وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌۭ﴾ … ﴿وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌۭ ۚ فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ﴾ … ﴿وَلَهُۥٓ أَخٌ أَوْ أُخْتٌۭ فَلِكُلِّ وَٰحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ﴾؛ (٣) والنساء ١٧٦ وفيها الأختُ فصاعدًا: ﴿وَلَهُۥٓ أُخْتٌۭ فَلَهَا نِصْفُ مَا تَرَكَ﴾ ﴿فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ﴾. وتعيينُ الأخوَينِ المُبهَمَين في الآيتين منصوصٌ عند ابن قدامة: في آية الكلالة الأخيرة «والمُرَادُ بذلك الإِخْوَةُ والأَخَوَاتُ مِن الأَبَوَيْنِ، أو مِن الأَبِ، بلا خِلافٍ بينَ أهْلِ العِلْمِ» (المغني، ج٩/ص٦)، وفي النساء ١٢ «والمُرَادُ بِهَذِه الآيةِ الْأَخُ والأُخْتُ مِنْ الأُمِّ، بإجْماعِ أَهْلِ الْعِلْمِ» (المغني، ج٩/ص٧).',
  verification_status = 'verified'
WHERE id = '53f94ba7-bb78-4557-9000-3037eba1cced'
