-- 9cdf8612 | ما هي أنصبة الميراث المقدَّرة (الفروض الستة)؟
UPDATE qa_questions SET
  answer = 'هي ستّةٌ محدودةٌ في كتاب الله: النصفُ، والربعُ، والثمنُ، والثلثان، والثلثُ، والسدس — كما حصرها ابن قدامة في المغني (ج٩/ص٣٥). ولكلٍّ منها موضعُه من آيات المواريث: النصفُ والثلثان والثلثُ والسدسُ في النساء ١١، والربعُ والثمنُ في النساء ١٢، ونصفُ الأخت وثلثا الأختين في النساء ١٧٦. ويستحقُّها ورثةٌ معيَّنون بحسب حال كلِّ وارثٍ ومن معه.',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): النساء ١١ و١٢ و١٧٦؛ المغني لابن قدامة: ج٩/ص٣٥ (باب أصول سهام الفرائض التي تعول) | الكلمات المفتاحية: الفروض الستة',
  evidence = 'نصَّ ابن قدامة على حصرها وعددِها في باب أصول سهام الفرائض: «وأصولُ المسائل كلُّها سَبعَةٌ؛ لأنَّ الفروضَ المحدودةَ في كتابِ اللَّه تعالى ستةٌ؛ النِّصْفُ، والرُّبْعُ، والثُمُنُ، والثُّلُثانِ، والثُّلُثُ، والسُّدُسُ» (المغني، ج٩/ص٣٥). ومواضعُها من الكتاب: النصفُ ﴿وَإِن كَانَتْ وَٰحِدَةًۭ فَلَهَا ٱلنِّصْفُ﴾ [النساء: ١١]، والربعُ والثمنُ ﴿فَإِن كَانَ لَهُنَّ وَلَدٌۭ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ﴾ ﴿فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ﴾ [النساء: ١٢]، والثلثان ﴿فَإِن كُنَّ نِسَآءًۭ فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ﴾ [النساء: ١١]، والثلثُ ﴿وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ﴾ [النساء: ١١]، والسدسُ ﴿وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌۭ﴾ [النساء: ١١].',
  verification_status = 'verified'
WHERE id = '9cdf8612-752b-42b3-ba35-317fb911d16d'
