  AND answer = 'النصف، والربع، والثمن، والثلثان، والثلث، والسدس — فروض مقدَّرة شرعًا يستحقها ورثة محددون بحسب حالة كل وارث وقربه من الميت.';

-- 0dcbef2e | ما هي قصة نبي الله يوسف عليه السلام مع إخوته؟
UPDATE qa_questions SET
  answer = 'حسده إخوتُه لمحبّة أبيهم يعقوبَ له ﴿لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا﴾ [يوسف: ٨]، فألقَوه في غيابة الجُبّ [يوسف: ١٥]، ثم بِيع بثمنٍ بخسٍ دراهمَ معدودة، واشتراه رجلٌ من مصر فأوصى امرأتَه بإكرام مثواه [يوسف: ٢٠-٢١]. ثم سُجن بعد أن استعصم ورأَوا الآيات [يوسف: ٣٣، ٣٥]، حتى مكّنه اللهُ في الأرض بعد تأويل رؤيا الملك وطلبِه خزائنَ الأرض [يوسف: ٥٤-٥٦]، فلقي إخوتَه بعدُ وعفا عنهم: ﴿لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ﴾ [يوسف: ٩٢]. وهي القصّةُ التي سمّاها اللهُ ﴿أَحْسَنَ ٱلْقَصَصِ﴾ [يوسف: ٣].',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): يوسف ٣ و٨ و١٥ و٢٠-٢١ و٣٣ و٣٥ و٥٤-٥٦ و٩٢ | الكلمات المفتاحية: قصة يوسف وإخوته',
  evidence = 'القصّةُ مسوقةٌ في سورة يوسف متّصلةً، وسمّاها اللهُ ﴿أَحْسَنَ ٱلْقَصَصِ﴾ [يوسف: ٣]. وأطوارُها بمواضعها: الحسدُ ﴿إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ﴾ [يوسف: ٨]؛ والجُبُّ ﴿فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ﴾ [يوسف: ١٥]؛ والبيعُ ﴿وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍۢ دَرَٰهِمَ مَعْدُودَةٍۢ﴾ [يوسف: ٢٠] — ومصرُ إنّما ذُكرت في المشتري لا في البائعين: ﴿وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ﴾ [يوسف: ٢١]؛ والسجنُ بعد استعصامه ﴿قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ﴾ [يوسف: ٣٣] ﴿ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْءَايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍۢ﴾ [يوسف: ٣٥]؛ والتمكينُ ﴿قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ ۖ إِنِّى حَفِيظٌ عَلِيمٌۭ﴾ ﴿وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ﴾ [يوسف: ٥٥-٥٦]؛ والعفوُ ﴿قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ ۖ يَغْفِرُ ٱللَّهُ لَكُمْ﴾ [يوسف: ٩٢].',
  verification_status = 'verified'
WHERE id = '0dcbef2e-03ef-4d1f-ad4c-11da0e575209'
  AND reference = 'سورة يوسف | الكلمات المفتاحية: قصة يوسف وإخوته'
  AND evidence = 'قصة كاملة مفصَّلة في سورة يوسف، وهي أطول قصة فردية متصلة في القرآن.'
  AND answer = 'حسده إخوته لمحبة أبيهم يعقوب له فألقوه في الجُبّ، فبيع عبدًا في مصر، ثم ابتُلي بالسجن ظلمًا، حتى مكّنه الله في الأرض بعد تأويل رؤيا الملك، فلقي إخوته لاحقًا وعفا عنهم رغم ما فعلوه به.';

-- 75ef7933 | كيف تحفظ الشريعة «حفظ المال» كمقصد أساسي؟
UPDATE qa_questions SET
  answer = 'حُفِظ المالُ من جانبَين. من جانب الوجود: بإباحة الكسب بالتجارة عن تراضٍ [النساء: ٢٩]، وإحلالِ البيع [البقرة: ٢٧٥]، وإيجابِ الزكاة فيه [البقرة: ٤٣]. ومن جانب العدم: بتحريم أكل أموال الناس بالباطل والتوصُّلِ إلى ذلك بالخصومة عند الحكّام [البقرة: ١٨٨]، وتحريمِ الربا [البقرة: ٢٧٥]، والميسرِ [المائدة: ٩٠]، وبإقامةِ حدِّ القطع على السارق والسارقة [المائدة: ٣٨].',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): البقرة ٤٣ و١٨٨ و٢٧٥، والنساء ٢٩، والمائدة ٣٨ و٩٠ | الكلمات المفتاحية: مقاصد الشريعة، حفظ المال، الضروريات الخمس',
  evidence = 'من جانب الوجود: إباحةُ التكسّب بالتجارة عن تراضٍ ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍۢ مِّنكُمْ﴾ [النساء: ٢٩]، وحِلُّ البيع ﴿وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ﴾ [البقرة: ٢٧٥]، وإيجابُ الزكاة ﴿وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ﴾ [البقرة: ٤٣]. ومن جانب العدم: تحريمُ أكل الأموال بالباطل بتمامِ الآية لا ببعضها ﴿وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًۭا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ﴾ [البقرة: ١٨٨]، وتحريمُ الربا ﴿وَحَرَّمَ ٱلرِّبَوٰا۟﴾ [البقرة: ٢٧٥]، والميسرِ ﴿إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَٰمُ رِجْسٌۭ مِّنْ عَمَلِ ٱلشَّيْطَٰنِ فَٱجْتَنِبُوهُ﴾ [المائدة: ٩٠]، وحدُّ السرقة ﴿وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا جَزَآءًۢ بِمَا كَسَبَا نَكَٰلًۭا مِّنَ ٱللَّهِ﴾ [المائدة: ٣٨].',
  verification_status = 'verified'
WHERE id = '75ef7933-3007-4777-8926-99e86fcdb50d'
  AND reference = 'سورة البقرة، الآية 188 | الكلمات المفتاحية: مقاصد الشريعة، حفظ المال، الضروريات الخمس'
  AND evidence = 'قال تعالى: «وَلَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ» (البقرة: 188)'
  AND answer = 'حفظت الشريعة المال من جانب الوجود بمشروعية الكسب والتجارة وإيجاب الزكاة لتنميته اجتماعيًا، ومن جانب العدم بتحريم السرقة والغصب والربا والقمار وأكل أموال الناس بالباطل، مع إيجاب الحدود والضمان على المعتدي.';

-- 3c21aed8 | ما هو الإيلاء في الفقه الإسلامي؟
UPDATE qa_questions SET
  answer = 'الإيلاءُ في الشرع هو الحَلِف على ترك وطء المرأة، كما حدَّه ابن قدامة في المغني (ج١١/ص٥). وضابطُ المدّة في متن الخِرَقيّ: أن يحلف بالله أن لا يطأ زوجتَه أكثرَ من أربعة أشهر. وأصلُه قولُه تعالى: ﴿لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍۢ﴾، فإن فاء فاللهُ غفورٌ رحيم، ﴿وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ﴾ [البقرة: ٢٢٦-٢٢٧]. فإذا انقضت المدّةُ طُولب بالفيئة، فإن لم يفعل أُمِر بالطلاق، فيُؤخَذ بالفيئة أو بالطلاق (المغني، ج١١/ص٤٤) — دفعًا للضرر عن الزوجة.',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): البقرة ٢٢٦-٢٢٧؛ المغني لابن قدامة: ج١١/ص٥ (كتاب الإيلاء) وج١١/ص٤٤ | الكلمات المفتاحية: الإيلاء، الطلاق، حقوق الزوجة',
  evidence = 'حدُّه عند ابن قدامة: «فأمَّا الإِيلاءُ فى الشَّرْعِ، فهو الحَلِفُ على تَرْكِ وَطْءِ المَرْأَةِ. والأصْلُ فِيهِ قولُ اللَّهِ تعالى» ثم ساق الآية (المغني، ج١١/ص٥)، وقيدُ المدّة في متن الخِرَقيّ الذي شرحه: «وَالْمُولِى الَّذِى يَحْلِفُ بِاللَّهِ عَزَّ وَجَلَّ أَنْ لَا يَطَأَ زوْجَتَهُ أَكْثَرَ مِنْ أَرْبَعَةِ أَشْهُرٍ». والأصلُ ﴿لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍۢ ۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ﴾ ﴿وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ﴾ [البقرة: ٢٢٦-٢٢٧] — وآيةُ ٢٢٧ هي موضعُ شقِّ الحكم الثاني، وكانت ساقطةً من الشاهد. وبعد انقضاء المدّة: «طُولِبَ بالفَيْئَةِ … فإنْ لم يَفعَلْ، أُمِرَ بالطَّلاقِ»، و«ويُؤْخَذُ بالفَيْئةِ، أو بالطلاقِ» (المغني، ج١١/ص٤٤).',
  verification_status = 'verified'
WHERE id = '3c21aed8-7cc7-446c-8c5b-fab2f98baf58'
  AND reference = 'سورة البقرة، الآية 226 | الكلمات المفتاحية: الإيلاء، الطلاق، حقوق الزوجة'
  AND evidence = 'قال تعالى: «لِّلَّذِينَ يُؤْلُونَ مِن نِّسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِن فَاءُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ» (البقرة: 226)'
  AND answer = 'الإيلاء هو حَلِف الزوج على ترك وطء زوجته مدة تزيد على أربعة أشهر، فإن مضت المدة ولم يرجع عن يمينه (الفيئة) أُجبر شرعًا على الفيئة أو الطلاق، دفعًا للضرر عن الزوجة من تعليقها بلا زوج حقيقي.';

-- 358aca26 | ما حكم العمل بالعلم بعد تعلّمه؟
UPDATE qa_questions SET
  answer = 'ذمَّ اللهُ من يقول ما لا يفعل، وبلَغ به أن جعله ﴿كَبُرَ مَقْتًا عِندَ ٱللَّهِ﴾ [الصف: ٢-٣]، فدلّ على وجوب أن يُتبِع طالبُ العلم علمَه عملًا وأن لا يقول ما لا يفعل. وفي الحديث: «وَالْقُرْآنُ حُجَّةٌ لَكَ أو عليك» (مسلم ٢٢٣)، فهو حجّةٌ للعامل به وعلى المخالف. والغايةُ من طلب العلم العملُ به والدعوةُ إليه لا مجرّدُ جمعه وحفظه.',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): الصف ٢-٣؛ صحيح مسلم (ت محمد فؤاد عبد الباقي): ٢٢٣ (ج١/ص٢٠٣، باب فضل الوضوء) | الكلمات المفتاحية: العمل بالعلم، طالب العلم، الإخلاص',
  evidence = 'نصُّ الآيتين برسم المصحف: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ﴾ ﴿كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ﴾ [الصف: ٢-٣] — والآيةُ الثانيةُ صرّحت بأنّ ذلك ‹كَبُرَ مَقْتًا عِندَ ٱللَّهِ›، وهو أشدُّ من مجرّد الذمّ. وأمّا كونُ الحجّة قد تكون على صاحبها، فلفظُه المحفوظُ في القرآن خاصّةً لا في مطلق العلم: «وَالْقُرْآنُ حُجَّةٌ لَكَ أو عليك» من حديث أبي مالك الأشعريّ (مسلم ٢٢٣، ج١/ص٢٠٣، باب فضل الوضوء).',
  verification_status = 'verified'
WHERE id = '358aca26-5e36-4bd4-a223-62ef210b46de'
  AND reference = 'سورة الصف، الآيتان 2-3 | الكلمات المفتاحية: العمل بالعلم، طالب العلم، الإخلاص'
  AND evidence = 'قال تعالى: «يَا أَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ * كَبُرَ مَقْتًا عِندَ اللَّهِ أَن تَقُولُوا مَا لَا تَفْعَلُونَ» (الصف: 2-3)'
  AND answer = 'يجب على طالب العلم أن يعمل بما تعلّمه، فالعلم بلا عمل حجة على صاحبه لا له، والغاية من طلب العلم هي العمل به والدعوة إليه لا مجرد جمعه وحفظه، وقد ذمّ الله من يقول ما لا يفعل.';

-- 7e84b591 | ما حكم زواج المسلم من امرأة كتابية (يهودية أو نصرانية)؟
UPDATE qa_questions SET
  answer = 'يجوز للمسلم أن ينكح المحصَنةَ من أهل الكتاب بنصّ ﴿وَٱلْمُحْصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ﴾ [المائدة: ٥]، والآيةُ قيّدت ذلك بإيتاء الأجور وبأن يكون الأزواجُ ﴿مُحْصِنِينَ غَيْرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍۢ﴾. وقرّر ابن قدامة أنّ للمسلم أن يبتدئ نكاح كتابيّة (المغني، ج١٠/ص٣٢). وأمّا نكاحُ المسلمة من غير المسلم فممنوعٌ بنصّ الكتاب: ﴿وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟﴾ [البقرة: ٢٢١]، ﴿لَا هُنَّ حِلٌّۭ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ﴾ [الممتحنة: ١٠].',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): المائدة ٥، والبقرة ٢٢١، والممتحنة ١٠؛ المغني لابن قدامة: ج١٠/ص٣٢ | الكلمات المفتاحية: زواج من كتابية، أهل الكتاب، النكاح',
  evidence = 'الآيةُ بتمام قيدِها لا مبتورةً عند ‹أُجُورَهُنَّ›: ﴿وَٱلْمُحْصَنَٰتُ مِنَ ٱلْمُؤْمِنَٰتِ وَٱلْمُحْصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍۢ﴾ [المائدة: ٥] — فالقيدُ ﴿مُحْصِنِينَ غَيْرَ مُسَٰفِحِينَ﴾ في الأزواج أنفسِهم، وهو الذي سقط بالبَتْر. وعقدُ المسلم على الكتابيّة ابتداءً مقرَّرٌ عند ابن قدامة: «لأنَّ للمُسْلِمِ أَنَّ يَبْتَدِئَ نكاحَ كتابيَّةٍ، فاسْتِدَامتُه أَوْلَى» (المغني، ج١٠/ص٣٢). وأمّا نكاحُ المسلمة من غير المسلم فمنصوصُ المنع في الكتاب، لا مجرَّدُ إجماعٍ مُرسَل: ﴿وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟﴾ [البقرة: ٢٢١]، و﴿لَا هُنَّ حِلٌّۭ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ﴾ [الممتحنة: ١٠].',
  verification_status = 'verified'
WHERE id = '7e84b591-b01f-47be-bd8c-6f1dad43a079'
  AND reference = 'سورة المائدة، الآية 5 | الكلمات المفتاحية: زواج من كتابية، أهل الكتاب، النكاح'
  AND evidence = 'قال تعالى: «وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِن قَبْلِكُمْ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ» (المائدة: 5)'
  AND answer = 'يجوز للمسلم أن يتزوج امرأة كتابية عفيفة محصنة عند جمهور الفقهاء، بخلاف نكاح المسلمة من غير المسلم فهو محرم بإجماع العلماء، صيانةً لدين المرأة وأولادها لأن الولاية في البيت للزوج.';

-- a293a3d8 | ما الترتيب الشرعي بين قضاء الدَّين وتنفيذ الوصية عند توزيع التركة؟
UPDATE qa_questions SET
  answer = 'يُقدَّم قضاءُ الدَّين على تنفيذ الوصيّة وإن قُدِّمت الوصيّةُ في تلاوة الآية ﴿مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصِى بِهَآ أَوْ دَيْنٍ﴾ [النساء: ١١]، ومستنَدُ التقديم ما رواه عليٌّ رضي الله عنه أنّ رسول الله ﷺ «قَضَى بالدَّيْنِ قَبْلَ الوَصِيَّةِ» أخرجه الترمذيّ، نقله ابن قدامة في المغني (ج٩/ص٧). ثم تُنفَّذ الوصيّةُ في حدود الثلث فما دونه لقوله ﷺ لسعدٍ: «الثُّلُثُ، وَالثُّلُثُ كَبِيرٌ، أَوْ كَثِيرٌ» (البخاري ١٢٩٥)، ثم يُقسَم الباقي على الورثة بالفرائض.',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): النساء ١١؛ المغني لابن قدامة: ج٩/ص٧؛ صحيح البخاري (ط السلطانية): ١٢٩٥ (ج٢/ص٨١، باب رثاء النبي ﷺ سعد بن خولة) | الكلمات المفتاحية: الوصية، الدين، الميراث',
  evidence = 'لفظُ الآية برسم المصحف: ﴿مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصِى بِهَآ أَوْ دَيْنٍ﴾ [النساء: ١١] — فالوصيّةُ مقدَّمةٌ في التلاوة. وتقديمُ الدَّين في التنفيذ منصوصٌ لا مُرسَل: نقل ابن قدامة «لما رُوِىَ عن عليٍّ، عليه السَّلَامُ، أنَّ رسُولَ اللهِ -صلى اللَّه عليه وسلم- قَضَى بالدَّيْنِ قَبْلَ الوَصِيَّةِ» ثم قال: «أَخْرَجَهُ التِّرْمِذِىُّ» (المغني، ج٩/ص٧). وحدُّ الوصيّة الثلثُ فما دونه بحديث سعد بن أبي وقّاص: «أَفَأَتَصَدَّقُ بِثُلُثَيْ مَالِي؟ قَالَ: لَا. فَقُلْتُ: بِالشَّطْرِ؟ فَقَالَ: لَا. ثُمَّ قَالَ: الثُّلُثُ، وَالثُّلُثُ كَبِيرٌ، أَوْ كَثِيرٌ» (البخاري ١٢٩٥، ج٢/ص٨١).',
  verification_status = 'verified'
WHERE id = 'a293a3d8-1af5-40a1-9caa-ca4969a4ff9a'
  AND reference = 'سورة النساء، الآية 11 | الكلمات المفتاحية: الوصية، الدين، الميراث'
  AND evidence = 'قال تعالى: «مِن بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ» (النساء: 11)'
  AND answer = 'أجمع الفقهاء على أن قضاء الدَّين يُقدَّم عمليًا على تنفيذ الوصية وإن ذكرت الآية الوصية أولًا، لأن الدَّين حق واجب لصاحبه بخلاف الوصية فهي تبرع، ثم تُنفَّذ الوصية في حدود الثلث، ثم يُقسَم الباقي على الورثة بالفرائض.';

-- eac5b364 | ما حكم تعدد الزوجات في الإسلام؟
UPDATE qa_questions SET
  answer = 'أُبيح للرجل أن يجمع بين أربعٍ فأقلَّ بنصّ ﴿فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ﴾، ولا يملك إمساك أكثرَ من أربعٍ كما نصّ ابن قدامة في المغني (ج١٠/ص١٤) بحديث «اخْتَرْ مِنْهنَّ أرْبعًا». فإن خاف ألّا يعدل لزمه الاقتصارُ على واحدة: ﴿فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَٰنُكُمْ ۚ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟﴾ [النساء: ٣]، فالتعليلُ في الآية نفسِها. فهو رخصةٌ مقيَّدةٌ بالعدل لا مطلقة، وليس واجبًا ولا مقصودًا لذاته.',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): النساء ٣؛ المغني لابن قدامة: ج١٠/ص١٤ | الكلمات المفتاحية: تعدد الزوجات، العدل، النكاح',
  evidence = 'الآيةُ بتمامها لا مبتورةً عند ‹فَوَٰحِدَةً›: ﴿وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا۟ فِى ٱلْيَتَٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَٰنُكُمْ ۚ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟﴾ [النساء: ٣] — وقولُه ﴿ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟﴾ هو تعليلُ الاقتصار، وكان ساقطًا بالبَتْر. وحدُّ الأربع منصوصٌ عند ابن قدامة: «ولا يَمْلِكُ إمْساكَ أكثَر من أربعٍ»، ودليلُه «ما رَوَى قَيْسُ بن الحارثِ، قال: أسْلَمْتُ وَتَحْتِى ثَمانِ نِسْوَةٍ، فأتَيْتُ النَّبِىَّ -صلى اللَّه عليه وسلم-، فقلتُ له ذلك، فقال: "اخْتَرْ مِنْهنَّ أرْبعًا"» رواه أحمد وأبو داود، وحديثُ غيلانَ بن سلمة «فأمَرَه رسولُ اللَّه -صلى اللَّه عليه وسلم- أن يتَخَيَّر منهنَّ أرْبعًا» رواه الترمذيّ (المغني، ج١٠/ص١٤).',
  verification_status = 'verified'
WHERE id = 'eac5b364-dc63-4cfd-b2c8-d047ddb49c2a'
  AND reference = 'سورة النساء، الآية 3 | الكلمات المفتاحية: تعدد الزوجات، العدل، النكاح'
  AND evidence = 'قال تعالى: «وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَىٰ فَانكِحُوا مَا طَابَ لَكُم مِّنَ النِّسَاءِ مَثْنَىٰ وَثُلَاثَ وَرُبَاعَ ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً» (النساء: 3)'
  AND answer = 'أباح الإسلام للرجل أن يتزوج حتى أربع نساء بشرط العدل بينهن في النفقة والمبيت والمعاملة الظاهرة، فإن خشي عدم العدل وجب عليه الاقتصار على زوجة واحدة، فالتعدد رخصة مقيدة بالعدل لا رخصة مطلقة، وليس واجبًا ولا مقصودًا لذاته.';
